WITH with_dims AS (SELECT src.*, b.price, b.cost FROM store_sales src LEFT JOIN products b ON src.product_id = b.id) SELECT product_id, CASE WHEN cost >= 700 THEN 'PREMIUM' ELSE 'STANDARD' END AS cost_tier, COUNT(DISTINCT store_id) AS distinct_store_ids, APPROX_PERCENTILE(units, 0.9) AS units_p90, GROUPING_ID() AS grouping_id FROM with_dims GROUP BY CUBE (product_id, CASE WHEN cost >= 700 THEN 'PREMIUM' ELSE 'STANDARD' END)
